export type UserRole = 'patient' | 'doctor' | 'pharmacist' | 'lab' | 'physiotherapy' | 'radiologist';

export type ApprovalStatus = 'pending' | 'approved' | 'rejected';

export interface User {
  id: string;
  username: string;
  phoneNumber: string;
  nationalId: string;
  role: UserRole;
  approvalStatus: ApprovalStatus;
  displayName: string;
  avatarIndex: number;
  biometricEnabled: boolean;
  createdAt: string;
}

export interface Medicine {
  id: string;
  name: string;
  genericName: string;
  manufacturer: string;
  dosageForm: string;
  strength: string;
  stockLevel?: number;
  expiryDate?: string;
  interactions?: string[];
}

export interface Prescription {
  id: string;
