            </Pressable>
          </View>
        }
      />

      <Pressable
        style={[
          styles.fab,
          {
            backgroundColor: theme.primary,
            bottom: tabBarHeight + Spacing.xl,
          },
          Shadows.fab,
        ]}
        onPress={addMedication}
      >
        <MaterialCommunityIcons name="plus" size={24} color={theme.buttonText} />
      </Pressable>
    </ThemedView>
