        );

      case 'prescriptions':
        return (
          <View style={styles.tabContent}>
            {prescriptions.length > 0 ? (
              prescriptions.map((prescription) => (
                <Card key={prescription.id} style={styles.section}>
                  <View style={styles.prescriptionHeader}>
